-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Parte 3 de 7. Requiere 01_esquema.sql (columnas profile, skills y
-- mindscapes de characters) y 04_personajes_zzz.sql.
--
-- Datos de los agentes de Zenless Zone Zero sacados de HoYoWiki, la wiki oficial de
-- HoYoverse, con los textos oficiales en espanol:
--   profile     -> sexo, afiliacion, estatura, cumpleanos, actores de voz y version.
--   skills      -> las seis categorias de tecnicas (ataque normal, evasion,
--                  tecnica de apoyo, tecnica especial, tecnica en cadena y
--                  habilidad fundamental) con sus valores por nivel y los
--                  materiales para subirlas.
--   mindscapes  -> los seis niveles de Cine mental.
-- Ademas, los agentes que no tenian biografia reciben el "Diseño de personaje"
-- de la wiki (los que ya tenian una se dejan como estan).
--
-- Sin ficha en la wiki todavia: zzz-roxy.
--
-- Solo actualiza agentes que ya existen; no crea ninguno. Se puede repetir.
--
-- Generado el 2026-09-15.

update public.characters as c
set profile = v.profile,
    skills = v.skills,
    mindscapes = v.mindscapes,
    biography_es = coalesce(c.biography_es, v.biography),
    biography_source_es = case when c.biography_es is null and v.biography is not null then v.source else c.biography_source_es end
from (
  values
  ('zzz-banyue', '[{"campo":"Versión de lanzamiento","valor":"2.4"},{"campo":"Sexo","valor":"Masculino"},{"campo":"Afiliación","valor":"Auditoría Krampus"},{"campo":"Estatura","valor":"200 cm"},{"campo":"Cumpleaños","valor":"24 de julio"},{"campo":"Amplificador exclusivo","valor":"Vajra iracundo"},{"campo":"Afiliación común","valor":"Dialyn, Zhao, Birkblick"},{"campo":"Equipamiento","valor":"Karma abrasador, Senda del asura, Apego sesgado"},{"campo":"Entradas relacionadas","valor":"Ning Qian, Altos de Failumen, Pináculo Yunkui, TOPS, Ye Shunguang, Ye Shunguang"},{"campo":"VA (CN)","valor":"Liu Beichen (刘北辰)"},{"campo":"VA (JP)","valor":"Hayami Shō (速水奨)"},{"campo":"VA (KO)","valor":"Kim Sang-baek (김상백)"},{"campo":"VA (EN)","valor":"(Próximamente)"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/08/26/7c4749265d45177f16044c76d9315db0_7689331585667217268.png","tecnicas":[{"nombre":"Ataque normal: Pico encumbrado","descripcion":"Pulsa para usarlo.\nEjecuta hasta cuatro ataques hacia delante, lo que inflige daño ígneo.\nDurante la ejecución de la habilidad, el nivel de interrupción aumenta."},{"nombre":"Ataque normal: Cúspide majestuosa","descripcion":"Pulsa para usarlo.\nEjecuta hasta cuatro ataques hacia delante, lo que inflige daño ígneo.\nDurante la ejecución de la habilidad, el nivel de resistencia a interrupción aumenta."},{"nombre":"Ataque normal: Cineración","descripcion":"Cuando no se encuentra en el estado de semblante de furia y tiene 120 ascuas furibundas, mantén pulsado para usarlo.\nInflige daño ígneo a los enemigos cercanos, y a continuación entra en el estado de semblante de furia."},{"nombre":"Ataque normal: Ignición","descripcion":"Cuando no está en combate, sus PV son superiores al 50 % y la cantidad de ascuas furibundas es inferior a 120, mantén pulsado para usarlo.\nBanyue consume activamente PV para recuperar ascuas furibundas.\nAl alcanzar 120 ascuas furibundas, Banyue entra directamente en el estado de semblante de furia.\nAl entrar en combate, obtiene una oportunidad para ejecutar esta habilidad.\nEn el modo expedición, este efecto puede activarse un máximo de una vez cada 180s.\nEl consumo de PV reduce los PV de Banyue hasta un 50 % de sus PV máx."},{"nombre":"Ataque normal: Derrumbe montañoso","descripcion":"Cuando Banyue se encuentra en el estado de semblante de furia, mantén pulsado para consumir 120 ascuas furibundas y usarlo.\nBanyue arroja una montaña enorme para atacar al enemigo, lo que inflige una gran cantidad de daño ígneo.\nTras la ejecución de la habilidad, Banyue sale del estado de semblante de furia.\nDurante la ejecución de la habilidad, el agente se vuelve invulnerable."},{"nombre":"Ataque normal: Destructor de montañas","descripcion":"Cuando Banyue se encuentra en el estado de semblante de furia, tras ejecutar dos técnicas especiales EX diferentes mediante una forma alternativa del ataque normal o pulsando rápidamente los comandos, mantén pulsado para usarlo.\nBanyue lanza sus cuentas hacia delante para confinar a los enemigos, lo que inflige una gran cantidad de daño ígneo.\nA continuación, Banyue ejecuta automáticamente el ataque normal: Derrumbe montañoso.\nDurante la ejecución de la habilidad, el agente se vuelve invulnerable."}],"atributos":[{"clave":"Ataque normal: Pico encumbrado","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["39.6%","43.2%","46.8%","50.4%","54%","57.6%","61.2%","64.8%","68.4%","72%","75.6%","79.2%","82.8%","86.4%","90%","93.6%"]},{"clave":"Multiplicador de dano de 2.° golpe","valores":["49.8%","54.4%","59%","63.6%","68.2%","72.8%","77.4%","82%","86.6%","91.2%","95.8%","100.3%","105%","109.6%","114.2%","118.8%"]},{"clave":"Multiplicador de daño de 3.er golpe","valores":["101.3%","110.6%","11